    # Initialize the set of visited nodes and the path stack
    visited = set()
    path = [start]

    # Set up the stack for traversal with a matrix to keep track of visited nodes
    stack = [(start, [start])]
    while stack:
        (vertex, path) = stack.pop()
        if vertex not in visited:
            adjacent_nodes = graph[vertex]
            if vertex == goal:
                return path + [goal]
            visited.add(vertex)
            for node in adjacent_nodes:
                if node not in visited:
                    stack.append((node, path + [node]))
    return None
