def find_path(graph, start, goal):
    if start == goal:
        return [start]  # If start and goal are the same, there's an immediate path of length 1.

    visited = set()
    queue = [[start]]  # Initialize the queue with a path containing the start node.

    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path  # If the current node is the goal, return the path.
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    new_path = list(path)
                    new_path.append(neighbor)
                    queue.append(new_path)  # Add the neighbor node to the queue with a new path.

    return None  # Return None if the goal is unreachable.
